// Both commands print a JSON report as the last thing on stdout. Pull those
// out so the execution log reads as a result, not a wall of text, and decide
// whether the run did its job.
//
// The report is pretty-printed, so it starts on a line that is just "{".
// Searching for the last brace instead would land inside a nested object.
// Written without backslash escapes on purpose: this code travels through JSON
// and n8n's editor, and every layer is another chance to lose one.
const NEWLINE = String.fromCharCode(10);

const report = (text) => {
  const lines = (text || '').split(NEWLINE).map((l) => l.trim());
  for (let i = lines.length - 1; i >= 0; i--) {
    if (lines[i] !== '{') continue;
    try {
      return JSON.parse(lines.slice(i).join(NEWLINE));
    } catch (_) {
      // Not the report; keep looking further up.
    }
  }
  return null;
};

// What went wrong in a command, in a few lines: its error if the node failed,
// otherwise the end of what it wrote to stderr.
const trouble = (out) => {
  if (out.error) return String(out.error.message || out.error).slice(0, 400);
  const tail = (out.stderr || '').trim().split(NEWLINE).slice(-4).join(' | ');
  return tail ? tail.slice(0, 400) : null;
};

const scrapeOut = $('Scrape new launches').first().json;
const retryOut = $('Retry held listings').first().json;
const scrape = report(scrapeOut.stdout);
const retry = report(retryOut.stdout);

// If every held listing is still unreachable from here, this host is blocked
// too, and the run is doing nothing useful. Say so loudly.
const blocked =
  retry !== null &&
  retry.held_listings_tried > 0 &&
  retry.unreachable === retry.held_listings_tried;

let verdict = 'ok';
if (scrape === null) {
  verdict = 'The scrape did not finish: ' + (trouble(scrapeOut) || 'no report printed');
} else if (retry === null) {
  verdict = 'The retry did not finish: ' + (trouble(retryOut) || 'no report printed');
} else if (blocked) {
  verdict = 'Product Hunt is blocking this machine too. Check the host, or use the official API.';
}

return [{ json: { scrape, retry, blocked, verdict } }];
